          citation_details: 'ಸಂಪುಟ V, ಪುಟಗಳು 422–435 (ರಾಜಕೀಯ ಓಡ್ರ ಮೂಲಗಳು, ಮಣ್ಣಿನ ಕಾಮಗಾರಿ ಎಂಜಿನಿಯರಿಂಗ್ ಮತ್ತು ಸೂರ್ಯವಂಶದ ಉಲ್ಲೇಖಗಳು)',
