      content: `ஓட்-ராஜ்புத், ஓட்-சத்திரிய மற்றும் அவர்களின் கிளை வம்சங்களின் வரலாற்றுப் பயணம் இந்திய சமூக, போர் மற்றும் பொறியியல் வரலாற்றின் மிகக் குறிப்பிடத்தக்க அத்தியாயங்களில் ஒன்றாகும். பண்டைய ஓட்ர தேசம் மற்றும் கங்கைச் சமவெளிகளில் இருந்து குஜராத், ராஜஸ்தான், தக்காணம், கர்நாடகம் மற்றும் தமிழ்நாடு வரை பரவியுள்ள இச்சமூகம், அரச வம்ச மரபு, பிரம்மாண்டமான மண் மற்றும் கற்சிற்பக் கலை மற்றும் தளராத விடாமுயற்சியின் நிலையான பாரம்பரியத்தைப் பாதுகாத்து வந்துள்ளது.

1. ஆதி தோற்றம் மற்றும் சூரியவம்சம் (சூரிய குலம்):
பாரம்பரிய வம்சாவளிகளும் வாய்மொழி வரலாறுகளும் ஓட் சமூகத்தின் தோற்றத்தை அயோத்தியின் பண்டைய சூரியவம்சத்துடன் தொடர்ந்து இணைக்கின்றன. முன்னோர் பேரரசர்களில் முதன்மையானவர்கள்:
- சாம்ராட் சகரர்: புராண சக்கரவர்த்தி; இவரது அறுபதாயிரம் புதல்வர்கள் பிரம்மாண்டமான கடல் படுகைகளைத் தோண்டி, மாபெரும் நில அகழ்வாராய்ச்சியின் முன்னோர் நினைவை நிறுவினர்.
- மகரிஷி ராஜா பகீரதன்: சகரரின் கொள்ளுப் பேரன்; புனித கங்கை நதியை பூமிக்குக் கொண்டுவர இடைவிடாத தவம் ("பகீரதப் பிரயத்தனம்") செய்தவர். சமூக உறுப்பினர்கள் பகீரதனை நீர் மேலாண்மை மற்றும் கால்வாய் அகழ்வின் தெய்வீகப் புரவலராக வணங்குகின்றனர்.
- ஸ்ரீ ராமன்: இக்ஷ்வாகு குலத்தின் மரியாதா புருஷோத்தமன்; அனைத்துக் கிளைகளிலும் உயர்ந்த தார்மீக லட்சியமாக வணங்கப்படுகிறார், மேலும் அவரது சூரியச் சின்னம் அரச முத்திரைகளிலும் சமூக முத்திரைகளிலும் பாதுகாக்கப்படுகிறது.

2. பண்டைய வரலாற்று சகாப்தம்: கலிங்க-ஓட்ர பேரரசர் காரவேலன்:
கி.மு. 2-ஆம்–1-ஆம் நூற்றாண்டில் மகாமேகவாகன (சேதி) வம்சத்தின் பேரரசர் காரவேலன் ஓட்ர-கலிங்கப் பேரரசை ஆட்சி செய்தார். புவனேஸ்வருக்கு அருகிலுள்ள உதயகிரி மலை உச்சியில் உள்ள அவரது புகழ்பெற்ற ஹாதிகும்பா கல்வெட்டு, பாதுகாப்புக் கோட்டைகளின் அரச கட்டுமானம், வெள்ளத் தடுப்புகளின் சீரமைப்பு மற்றும் பண்டைய கால்வாயைக் கலிங்கநகரி வரை விரிவுபடுத்தியதைத் தெளிவாக ஆவணப்படுத்துகிறது. பேரரச அதிகாரம், இராணுவ விரிவாக்கம் மற்றும் நீர்-பொறியியல் ஆளுமை ஆகியவற்றின் இந்த ஆழமான சங்கமமே பண்டைய ஓட்ர நாகரிகத்தின் தனிச்சிறப்பு என்று வரலாற்றாசிரியர்கள் குறிப்பிடுகின்றனர்.

3. சொற்பிறப்பியல் மற்றும் பிராந்தியப் பெயர்கள்:
இரண்டாயிரம் ஆண்டுகால புவியியல் இடப்பெயர்வில் முன்னோர் இனப் பெயரான 'ஓட்ர' (பிராகிருதம்: ஒட்ட / ஒட்ட-ராஜா) பல்வேறு பிராந்தியப் பெயர்களாகப் பரிணமித்தது:
- ஓட்: வட மற்றும் மேற்கு இந்தியாவில் (ராஜஸ்தான், பஞ்சாப், ஹரியானா, சிந்து மற்றும் டெல்லி) வழக்கத்தில் உள்ள வரலாற்றுப் பெயர்.
- ஓட்-ராஜ்புத்: மேற்கு இந்தியாவில் கோட்டை கட்டுமானம் மற்றும் இராணுவப் பாதுகாப்புடன் தொடர்புடைய பாரம்பரிய சத்திரிய அந்தஸ்து மற்றும் போர்வீரர்-கட்டுமான அடையாளத்தைப் பாதுகாக்கும் பெயர்.
- ஓட்ர / ஒளட்ர: மத்திய ஒடிசாவின் பண்டைய மக்கள், அரசு மற்றும் பிராந்தியத்தைக் குறிக்கும் செவ்வியல் சமஸ்கிருதப் பெயர்.
- ஓட்-சத்திரிய: சூரியவம்ச மன்னர்களுடனான வம்சத் தொடர்புகளைப் பிரதிபலிக்கும் வேத கால போர்வீரர்-ஆட்சியாளர் வர்ணத்தின் அதிகாரப்பூர்வ நவீன உறுதிப்பாடு.
- ஒட்டெ / வட்டெ: தெலுங்கு பேசும் கடலோர ஆந்திரா, ராயலசீமா மற்றும் தெலுங்கானாவில் ஏற்பட்ட ஒலி மாற்றம் (இங்கு தொடக்க எழுத்தான 'ஓ' பெரும்பாலும் 'வோ' அல்லது 'வ' என மாறுகிறது).
- ஒட்டெராஜுலு / வட்டெராஜுலு / வடியராஜுலு: கஜபதி மற்றும் விஜயநகரப் பேரரசுகளின் கீழ் இராணுவச் சேவை, கோட்டைத் தளபதி பதவிகள் மற்றும் நில மானியங்களைக் குறிக்கும் வகையில் "ராஜுலு" / "ராஜு" (அரசன் / சத்திரிய ஆட்சியாளர்) என்ற அரச தெலுங்குப் பட்டத்தைக் கொண்ட பெயர்கள்.
- வட்டர்: மகாராஷ்டிரா, கர்நாடகா மற்றும் கோவாவில் புகழ்பெற்ற கற்சிற்பிகள், கோட்டை கட்டுபவர்கள் மற்றும் கால்வாய் பொறியாளர்களைக் குறிக்கும் பெயர்.
- ஒட்டர்: தமிழ்நாட்டில் (கொங்கு நாடு, சேலம், கோயம்புத்தூர், தஞ்சாவூர்) கஜபதி ஆளுநர்களின் தெற்குப் படையெடுப்புகளின் போது குடியேறியவர்களைக் குறிக்கும் பெயர்.

4. புனித கலாச்சார வீராங்கனைகள் மற்றும் ஆன்மீகக் காவலர்கள்:
- தேவி ஜஸ்மா ஓடன் (ஜஸ்மா தேவி): கி.பி. 11–12-ஆம் நூற்றாண்டில் சோலங்கி மன்னன் சித்தராஜ ஜெயசிங்கனின் ஆட்சியில் பதான் நகரில் புகழ்பெற்ற சஹஸ்ரலிங்க ஏரி கட்டப்பட்டபோது, ஜஸ்மா ஓடன் சத்திரிய கற்பு, திருமணப் பக்தி மற்றும் கொடுங்கோன்மைக்கு எதிரான எதிர்ப்பின் உன்னத அடையாளமாகத் திகழ்ந்தார். தன் மானத்தைக் காக்கத் தன்னுயிர் ஈந்த அவர், இன்றும் குஜராத், ராஜஸ்தான் மற்றும் மத்தியப் பிரதேசம் முழுவதும் மாதா ஜஸ்மா தேவியாக வணங்கப்படுகிறார்.
- சோலாப்பூர் சிவயோகி சித்தராமேஸ்வரர்: 12-ஆம் நூற்றாண்டில் கல்யாண சரண ஆன்மீக இயக்கத்தின் போது, மகான் யோகி சித்தராமேஸ்வரர் பொது நீர் பாதுகாப்பிற்குத் தலைமை தாங்கி, வட்டர்/ஒட்டர் கலைஞர்களின் அயராத உழைப்பால் சோலாப்பூரில் பிரம்மாண்டமான நீர்த்தேக்கங்களையும் 68 சிவலிங்கங்களையும் கட்டினார். அவர் கர்நாடகம் மற்றும் மகாராஷ்டிரம் முழுவதும் சமூகத்தின் காவல் துறவியாகப் போற்றப்படுகிறார்.

5. புவியியல் பரவல் மற்றும் வரலாற்றுப் பாதைகள்:
- ராஜஸ்தான், சிந்து மற்றும் வடக்குப் பகுதி: கட்டிடக் கலை, அரச கோட்டை கட்டுமானம் (சித்தோர்கர், ஜெய்சால்மர்) மற்றும் கால்வாய் அகழ்வில் ஈடுபட்டுள்ள ஓட்-ராஜ்புத்திரர்கள்.
- குஜராத் (பதான், சௌராஷ்டிரா, அகமதாபாத்): ஜஸ்மா தேவி மரபின் பாதுகாவலர்கள் மற்றும் படிக்கிணறுகள் (வாவ்) மற்றும் நீர்த்தேக்கங்களின் பாரம்பரிய வல்லுநர்கள்.
- மகாராஷ்டிரா (சோலாப்பூர், புனே, மராத்வாடா, விதர்பா): சித்தராமேஸ்வரரின் குடிமைக் கட்டுமானங்கள் மற்றும் மராட்டியக் கோட்டைப் பாதுகாப்புடன் வரலாற்று ரீதியாகப் பிணைக்கப்பட்ட வட்டர் குடியிருப்புகள்.
- கர்நாடகா (பாகல்கோட், பெலகாவி, பீஜப்பூர், சித்ரதுர்கா, பெங்களூரு, பல்லாரி): அரச கஜபதி இராணுவ முகாம்கள் (மலேபென்னூரில் வீரபத்ர தேவர்) மற்றும் சரண மரபுகள் இரண்டையும் போற்றும் முக்கிய மக்கள் தொகை.
- ஆந்திரப் பிரதேசம் மற்றும் தெலுங்கானா (கோதாவரி, கிருஷ்ணா, குண்டூர், பல்நாடு, ராயலசீமா): கொண்டவீடு, பெல்லம்கொண்டா மற்றும் ஸ்ரீசைலம் கோட்டைக் காவற்படைகளுடன் வரலாற்றுத் தொடர்புகளைக் கொண்ட ஒட்டெராஜுலு, வட்டெராஜுலு மற்றும் வடியராஜுலு என அறியப்படுபவர்கள்.
- தமிழ்நாடு (திருச்சிராப்பள்ளி, சேலம், கோயம்புத்தூர், தஞ்சாவூர்): காவிரிப் படுகை வரை குமார ஹம்வீர தேவரின் தெற்குப் படையெடுப்புகளின் போது வருகை தந்த முன்னோர்களின் வழித்தோன்றல்களான ஒட்டர்கள்.
- ஒடிசா: மகாநதி, கட்டக் மற்றும் பூரியை மையமாகக் கொண்ட ஓட்ர தேசத்தின் பூர்வீகத் தாயகம்.`
