      summary: 'ಕೊಲ್ಲೇಟಿ ಸರಸ್ಸು (ಕೊಲ್ಲೇರು ಸರೋವರ), ಕೊಲ್ಲೇಟಿಕೋಟದ ದ್ವೀಪ ಕೋಟೆ, ಅಧಿಷ್ಠಾತ್ರಿ ವೀರ-ಮಾತೃ ದೇವತೆ ಶ್ರೀ ಪೆದ್ದಿಂಟ್ಲಮ್ಮ ತಲ್ಲಿ, ಗಜಪತಿ-ಒಡಿಯರಾಜು ಸೈನಿಕ ನೆಲೆಯ ರಕ್ಷಣಾ ವ್ಯವಸ್ಥೆಗಳು ಮತ್ತು ವಾರ್ಷಿಕ ಫಾಲ್ಗುಣ ಪೂರ್ಣಿಮಾ ತೀರ್ಥಂನ ಜೀವಂತ ಸಂಪ್ರದಾಯದ ಕುರಿತಾದ ಸಮಗ್ರ ಐತಿಹಾಸಿಕ ಮತ್ತು ಸಾಂಸ್ಕೃತಿಕ ದಾಖಲೆ.',
