      content: `கடலோர ஆந்திரப் பிரதேசத்தில் கிருஷ்ணா மற்றும் கோதாவரி நதிகளின் வளமான டெல்டாக்களுக்கு இடையில் இந்தியாவின் மிகப்பெரிய இயற்கை நன்னீர் ஏரிகள் மற்றும் ஈரநிலச் சூழலியல் அமைப்புகளில் ஒன்றான கொல்லேடி சரசு (கொல்லேரு ஏரி) அமைந்துள்ளது. வரலாற்று ரீதியாக நவீன ஏலூரு மற்றும் கிருஷ்ணா மாவட்டங்களில் (கைகலூருக்கு அருகில்) பரவியுள்ள கொல்லேடி சரசு வெறும் சூழலியல் அதிசயம் மட்டுமல்ல: ஆயிரம் ஆண்டுகளுக்கும் மேலாக இது ஊடுருவ முடியாத இயற்கை நீர் அரணாகச் செயல்பட்டது, மேலும் இதன் மையத் தீவுக் கோட்டையான கொல்லேடிகோட்டா இராணுவ வரலாற்றில் முதன்மையான "ஜல துர்க்கம்" (நீர் கோட்டை) எனப் போற்றப்பட்டது.

1. கொல்லேடி சரசின் (கொல்லேரு ஏரி) வரலாற்றுப் புவியியல்:
செவ்வியல் சமஸ்கிருதக் கல்வெட்டுகளிலும் தெலுங்கு இலக்கியத்திலும் கொல்லேரு "கொலனு" (ஏரி / குளம்) என்று அழைக்கப்படுகிறது, மேலும் அதன் ஆட்சியாளர்கள் "கொலனி-நாயக்கர்கள்" அல்லது ஏரியின் அதிபதிகள் என்று அழைக்கப்பட்டனர். பருவமழைக் காலங்களில் நூற்றுக்கணக்கான சதுர மைல்கள் பரந்து விரியும் இந்த ஏரி, அடர்ந்த சதுப்பு நிலங்கள், யானைப் புல் மற்றும் சிக்கலான நீர்வழிகளால் சூழப்பட்ட இயற்கை அகழியை உருவாக்கியது. வழக்கமான குதிரைப்படை மற்றும் காலாட்படையுடன் ஏரியைக் கடக்க முயலும் எதிரிப் படைகள் வண்டல் மண்ணிலும் ஆபத்தான நீரோட்டங்களிலும் சிக்கிச் செயலற்றுப் போயின; இதனால் கொல்லேடிகோட்டா தீபகற்ப இந்தியாவின் மிகவும் வலிமையான பாதுகாப்புக் கோட்டைகளில் ஒன்றாகத் திகழ்ந்தது.

2. கஜபதி மற்றும் ஒடியராஜு கோட்டைப் படை முகாம்:
15-ஆம் நூற்றாண்டில் பேரரசர் கபிலேந்திர தேவ கஜபதியும் அவரது வீரம் செறிந்த புதல்வர் குமார ஹம்வீர தேவரும் கடலோர ஆந்திரா வழியாகக் காவிரி நதி வரை வெற்றிப் பயணம் மேற்கொண்டபோது, ராஜமகேந்திரவரம், கொண்டபல்லி மற்றும் கொண்டவீடு இடையே விநியோகப் பாதைகளைப் பராமரிக்க கஜபதி படைகள் முக்கிய இராணுவ முகாம்களை நிறுவின.
சூரியவம்ச ஒடியராஜு மற்றும் தொடர்புடைய சத்திரிய போர் வம்சத்தினர் கொல்லேடிகோட்டா தீவுக் கோட்டையைப் பாதுகாத்தனர். உள்ளூர் நீர் மாலுமிகள் தட்டையான அடிப்பகுதி கொண்ட படகுகளைப் ("தோனி லு" / சங்கம்) பயன்படுத்தினர், மேலும் நீருக்கடியில் கட்டை தடுப்புகளையும் நாணல் மறைவிடங்களையும் உருவாக்கினர்; இதன் மூலம் பாதுகாவலர்கள் கொல்லேடி சரசின் பனிமூட்டத்தில் கண்ணுக்குத் தெரியாமல் இருந்துகொண்டே படையெடுப்பாளர்களைத் தாக்க முடிந்தது. கொல்லேருவின் ஆழங்களைக் கடக்க முயன்ற சுல்தானியப் படைப்பிரிவுகள் பேரழிவு தரும் தோல்விகளைச் சந்தித்தன என்று பாமினிப் போர்களின் வரலாற்று ஆவணங்கள் கூறுகின்றன.

3. ஸ்ரீ கொல்லேடிகோட்டா பெத்திண்ட்லம்மா தல்லி: முதன்மை போர்-தாய் தெய்வம்:
தீவுக் கோட்டையின் மையத்தில் ஸ்ரீ கொல்லேடிகோட்டா பெத்திண்ட்லம்மா தல்லியின் பண்டைய, புனிதமான கோயில் அமைந்துள்ளது. "பெத்திண்ட்லம்மா" என்ற பெயருக்கு "பெரிய / மூத்த அரச குடும்பத்தின் (பெத்தில்லு) தாய்" என்று பொருள்; இது ஆளும் சத்திரியர்கள், கோட்டைத் தளபதிகள் மற்றும் உள்ளூர் ஏரி சகோதரத்துவத்தின் குலதெய்வமாகவும் உயர்ந்த ஆன்மீகத் தாயாகவும் அவளது பங்கைப் பிரதிபலிக்கிறது.
சமூகத்தால் பாதுகாக்கப்பட்ட பிராந்திய கைஃபியத்துகள் மற்றும் வாய்மொழி மரபுகளின்படி:
- அன்னை தீவுக் கோட்டையின் தெய்வீகக் காவலராகத் திகழ்ந்தாள். ஏரியின் குறுக்கே கடற்படைப் பாதுகாப்பு அல்லது இராணுவத் தாக்குதல்களுக்குப் புறப்படும் முன், கஜபதி மற்றும் ஒடியராஜு தளபதிகள் புனித சக்தி பூஜைகளைச் செய்து, அவளது திருவடிகளில் ஆசீர்வதிக்கப்பட்ட வாள்களைப் பெற்றனர்.
- புகழ்பெற்ற முற்றுகைகளின் போது, படையெடுக்கும் படைகள் இருளின் மறைவில் ஏரிக் கால்வாய்களைக் கடக்க முயன்றபோது, பெத்திண்ட்லம்மா தல்லி நீரின் மீது அடர்ந்த பனிமூட்டத்தை உருவாக்கி, எதிரிகளைத் திசைதிருப்பிப் பாதுகாவலர்களை வெற்றிக்கு வழிநடத்தினாள் என்று கூறப்படுகிறது.
- பெத்திண்ட்லம்மா கோயிலுக்கு அருகிலேயே ஸ்ரீ கோகர்ணேஸ்வர சுவாமி (சிவபெருமான்) கோயில் அமைந்துள்ளது; இது அந்நிய ஆக்கிரமிப்புகளுக்கு எதிராகத் தீவுக் கோட்டையைப் புனிதப்படுத்திய வலிமையான சக்தி-சிவ சான்னித்தியத்தை நிறுவியது.

4. வாழும் மரபு: வருடாந்திர பெத்திண்ட்லம்மா ஜாதரா (தீர்த்தம்):
பெத்திண்ட்லம்மா தல்லியின் வழிபாடு பல நூற்றாண்டுகளாகத் தடையின்றித் தொடர்கிறது. ஒவ்வொரு ஆண்டும் புனித பங்குனி சுத்த பௌர்ணமி (பிப்ரவரி–மார்ச் மாதங்களில் ஹோலி / வசந்தோற்சவ விழாக் காலத்தில்) அன்று வரலாற்றுச் சிறப்புமிக்க "கொல்லேடிகோட்டா பெத்திண்ட்லம்மா தீர்த்தம் / ஜாதரா" இணையற்ற பக்தியுடன் கொண்டாடப்படுகிறது.
ஒடியராஜு சத்திரிய குடும்பங்கள், விவசாயிகள், மீனவர்கள் மற்றும் ஆந்திரப் பிரதேசம் மற்றும் அண்டை மாநிலங்களைச் சேர்ந்த பக்தர்கள் உட்பட இலட்சக்கணக்கானோர் கொல்லேடிகோட்டாவில் கூடுகின்றனர். பக்தர்கள் வரலாற்று ரீதியாகப் படகு அணிகள் மூலம் ஏரி நீரைக் கடந்து அன்னைக்கு மஞ்சள், குங்குமம், புனித மஞ்சள் கயிறுகள் மற்றும் பட்டு ஆடைகளைக் காணிக்கையாகச் செலுத்தினர்.

5. வரலாற்று மரபு மற்றும் கலாச்சாரத் தொடர்ச்சி:
கொல்லேடிகோட்டா பெத்திண்ட்லம்மா தல்லி மற்றும் கொல்லேடி சரசு ஆகியவை போர் பாதுகாப்பு, சுற்றுச்சூழல் பராமரிப்பு மற்றும் வாழும் நாட்டுப்புற-பக்தி மரபு ஆகியவற்றின் இணக்கமான சங்கமத்தை வெளிப்படுத்துகின்றன. சூரியவம்ச ஒடியராஜு சத்திரிய வலைத்தளம் ஓட்ர தேசம் மற்றும் அதன் தெற்குப் பரவலின் நாகரிக நினைவைப் போற்றும் வேளையில், கொல்லேடிகோட்டா தீவுக் கோட்டை போர்வீரர்களின் வீரத்திற்கும் அவர்களின் போர்-தாய் ஸ்ரீ பெத்திண்ட்லம்மா தல்லியின் அன்பான பாதுகாப்பிற்கும் ஒரு நிலையான நினைவுச்சின்னமாக நிற்கிறது.`
