      content: `किनारी आंध्र प्रदेशातील कृष्णा आणि गोदावरी नद्यांच्या सुपीक त्रिभुज प्रदेशांच्या दरम्यान भारतातील सर्वात मोठ्या नैसर्गिक गोड्या पाण्याच्या सरोवरांपैकी आणि पाणथळ परिसंस्थांपैकी एक असलेले कोल्लेटी सरसू (कोल्लेरू सरोवर) वसलेले आहे. ऐतिहासिकदृष्ट्या आधुनिक एलुरू आणि कृष्णा जिल्ह्यांमध्ये (कैकलुरूजवळ) पसरलेले कोल्लेटी सरसू केवळ एका नैसर्गिक आश्चर्यापेक्षा कितीतरी अधिक होते: एका सहस्राब्दीहून अधिक काळ त्याने एक अभेद्य नैसर्गिक जल तटबंदी म्हणून काम केले आणि त्याच्या मध्यवर्ती बेट किल्ल्याला, कोल्लेटीकोटाला, लष्करी इतिहासात एक प्रमुख "जलदुर्ग" म्हणून गौरवले गेले.

१. कोल्लेटी सरसूचे (कोल्लेरू सरोवर) ऐतिहासिक भूगोल:
अभिजात संस्कृत शिलालेख आणि तेलुगू साहित्यात कोल्लेरूला "कोलनू" (सरोवर / तलाव) म्हणून ओळखले जाते आणि त्याच्या शासकांना "कोलनी-नायक" किंवा सरोवराचे अधिपती म्हटले जाई. पावसाळ्यात शेकडो चौरस मैल पसरलेले हे सरोवर दाट दलदल, हत्ती गवत आणि चक्रव्यूहासारख्या जलमार्गांनी वेढलेला एक नैसर्गिक खंदक तयार करत असे. नेहमीच्या घोडदळ आणि पायदळासह सरोवर ओलांडण्याचा प्रयत्न करणारे शत्रूचे सैन्य गाळ आणि धोकादायक पाण्याच्या प्रवाहात लगेचच अडकून पडत असे, ज्यामुळे कोल्लेटीकोटा हा द्वीपकल्पीय भारतातील सर्वात अजिंक्य संरक्षणात्मक गडांपैकी एक बनला.

२. गजपती आणि ओडियाराजू किल्ला लष्करी तळ:
१५ व्या शतकात जेव्हा सम्राट कपिलेन्द्र देव गजपती आणि त्यांचे पराक्रमी पुत्र कुमार हम्वीर देव यांनी किनारी आंध्रमधून कावेरी नदीपर्यंत विजय मोहीम राबवली, तेव्हा गजपती सैन्याने राजमहेंद्रवरम, कोंडापल्ली आणि कोंडवीडू दरम्यान पुरवठा मार्ग सुरळीत ठेवण्यासाठी मोक्याची लष्करी ठाणी स्थापन केली.
सूर्यवंश ओडियाराजू आणि संलग्न क्षत्रिय योद्धा कुळांनी कोल्लेटीकोटाच्या बेट किल्ल्याचे रक्षण केले. स्थानिक जल-नावाड्यांनी सपाट तळाच्या होड्यांचा ("दोनी लू" / संगम) वापर केला आणि पाण्याखालील कुंपण व लव्हाळ्यांचे आडोसे तयार केले, ज्यामुळे रक्षकांना कोल्लेटी सरसूच्या धुक्यात अदृश्य राहून आक्रमकांवर छुपे हल्ले करणे शक्य झाले. बहमनी युद्धांच्या ऐतिहासिक नोंदी सांगतात की कोल्लेरूची अज्ञात खोली पार करण्याच्या प्रयत्नात सुलतानशाहीच्या तुकड्यांना दारुण पराभवाला सामोरे जावे लागले.

३. श्री कोल्लेटीकोटा पेद्दिंट्लम्मा तल्ली: अधिष्ठात्री योद्धा-माता:
बेट किल्ल्याच्या मध्यभागी श्री कोल्लेटीकोटा पेद्दिंट्लम्मा तल्लीचे प्राचीन, पवित्र मंदिर उभे आहे. "पेद्दिंट्लम्मा" या पदवीचा अर्थ "मोठ्या / ज्येष्ठ राजघराण्याची (पेद्दिल्लू) माता" असा होतो, जे सत्ताधारी क्षत्रिय, किल्लेदार आणि स्थानिक सरोवर बंधुभावाची कुलदेवता व सार्वभौम आध्यात्मिक मातृशक्ती म्हणून तिची भूमिका दर्शवते.
समुदायाने जपलेल्या प्रादेशिक कैफियती आणि मौखिक परंपरांनुसार:
- देवीने बेट किल्ल्याची दिव्य पहारेकरी म्हणून काम केले. सरोवरापलीकडे आरमारी संरक्षण किंवा लष्करी मोहिमांवर जाण्यापूर्वी, गजपती आणि ओडियाराजू सेनापती भक्तीभावाने शक्ती पूजा करत आणि तिच्या चरणकमलांवर आशीर्वादित केलेल्या तलवारी स्वीकारत असत.
- पौराणिक वेढ्यांच्या वेळी जेव्हा आक्रमक सैन्याने अंधाराचा फायदा घेऊन सरोवराचे कालवे ओलांडण्याचा प्रयत्न केला, तेव्हा पेद्दिंट्लम्मा तल्लीने पाण्यावर दाट धुके निर्माण करून आक्रमकांना दिशाहीन केले आणि रक्षकांना विजयाकडे नेले असे सांगितले जाते.
- पेद्दिंट्लम्मा मंदिराच्या शेजारीच श्री गोकर्णेश्वर स्वामींचे (भगवान शिव) प्राचीन मंदिर आहे, ज्याने परकीय आक्रमणाविरुद्ध बेट किल्ल्याला पावन करणारे शक्तिशाली शक्ती-शिव सान्निध्य प्रस्थापित केले.

४. जिवंत परंपरा: वार्षिक पेद्दिंट्लम्मा जत्रा (तीर्थम):
पेद्दिंट्लम्मा तल्लीची उपासना शतकानुशतके अखंड सुरू आहे. दरवर्षी पवित्र फाल्गुन शुद्ध पौर्णिमेला (फेब्रुवारी–मार्चमधील होळी / वसंतोत्सव सणाच्या काळात) ऐतिहासिक "कोल्लेटीकोटा पेद्दिंट्लम्मा तीर्थम / जत्रा" अपूर्व भक्तीभावाने साजरी केली जाते.
ओडियाराजू क्षत्रिय कुटुंबे, शेतकरी, मच्छीमार आणि आंध्र प्रदेश व शेजारील राज्यांतील भाविकांसह लाखो भक्त कोल्लेटीकोटा येथे एकत्र येतात. भाविक ऐतिहासिकदृष्ट्या होड्यांच्या ताफ्याने सरोवराचे पाणी ओलांडून मातेला हळद, कुंकू, पवित्र पिवळे दोरे आणि रेशमी वस्त्रे अर्पण करत असत.

५. ऐतिहासिक वारसा आणि सांस्कृतिक सातत्य:
कोल्लेटीकोटा पेद्दिंट्लम्मा तल्ली आणि कोल्लेटी सरसू हे लष्करी संरक्षण, पर्यावरण संवर्धन आणि जिवंत लोक-भक्ती वारशाचा सुसंवादी संगम साकारतात. सूर्यवंश ओडियाराजू क्षत्रिय पोर्टल ओड्र देश आणि त्याच्या दक्षिणेकडील विस्ताराच्या सांस्कृतिक स्मृतींचा सन्मान करत असताना, कोल्लेटीकोटाचा बेट किल्ला योद्ध्यांच्या शौर्याचे आणि त्यांची योद्धा-माता श्री पेद्दिंट्लम्मा तल्लीच्या वात्सल्यपूर्ण रक्षणाचे शाश्वत स्मारक म्हणून उभा आहे.`
