          year_or_era: 'ପ୍ରାୟ ଖ୍ରୀଷ୍ଟପୂର୍ବ ୧ମ ଶତାବ୍ଦୀ',
          citation_details: 'ଉଦୟଗିରି ପାହାଡ଼, ଭୁବନେଶ୍ୱର; ଶାସନ କାଳର ଇତିହାସ ଓ କେନାଲ ନିର୍ମାଣ',
